from pathlib import Path

p = Path('index.html')
text = p.read_text(encoding='utf-8')

def replace_once(old, new, label):
    global text
    if new in text:
        return
    if old not in text:
        raise SystemExit(f'patch target not found: {label}')
    text = text.replace(old, new, 1)

text = text.replace('<title>심연 회수대 - v1.4 방/복도/문 프로토타입</title>', '<title>심연 회수대 - v1.8 전투/장비 업데이트</title>')
text = text.replace('• 몬스터는 시간이 지나면 재생성', '• 몬스터는 층을 이동할 때 다시 재생성')
if '• 던전 안에서도 가방의 무기를 즉시 장착 가능' not in text:
    text = text.replace('• 몬스터는 층을 이동할 때 다시 재생성<br>', '• 몬스터는 층을 이동할 때 다시 재생성<br>• 던전 안에서도 가방의 무기를 즉시 장착 가능<br>')
if '.equipMini{' not in text:
    text = text.replace('.lootEntry{display:grid;grid-template-columns:1fr auto;gap:6px;padding:7px 0;border-bottom:1px solid #29333f}', '.lootEntry{display:grid;grid-template-columns:1fr auto;gap:6px;padding:7px 0;border-bottom:1px solid #29333f}.equipMini{margin-top:5px;padding:4px 6px;font-size:10px;width:100%}.slot.weaponSlot{border-color:#435468}.slot.weaponSlot:hover{border-color:#6b86a5}')

