replace_once(
"function escapeRun(viaScroll=false){profile.gold+=run.coins;run.inv.forEach(it=>{if(it.kind==='material'){profile.materials[it.material]=(profile.materials[it.material]||0)+it.qty}else profile.stash.push(it)});profile.ammo.arrow+=run.ammo.arrow;profile.ammo.mana+=run.ammo.mana;profile.ammo.bullet+=run.ammo.bullet;profile.potions+=run.potions;profile.scrolls+=run.scrolls;profile.weapons[run.weapon.type].durability=run.weapon.durability;save();toast(viaScroll?'귀환 성공! 전리품을 회수했습니다.':'B1 탈출 성공! 전리품을 회수했습니다.');endRun(false)}\nfunction endRun(lost=true){if(lost)profile.weapons[run.weapon.type].durability=Math.max(0,run.weapon.durability);save();run=null;$('#dungeonView').classList.add('hidden');$('#lobbyView').classList.remove('hidden');closeLoot();renderLobby()}",
"function restoreCarriedProfileGear(){if(!run)return;const all=[run.weapon,...run.inv];for(const it of all){if(it&&it.kind==='weapon'&&it._fromProfile&&it._profileType){profile.weapons[it._profileType]=cleanWeaponItem(it)}}}\nfunction escapeRun(viaScroll=false){profile.gold+=run.coins;restoreCarriedProfileGear();const currentIsLoot=run.weapon&&run.weapon.kind==='weapon'&&!run.weapon._fromProfile;for(const it of run.inv){if(it.kind==='material'){profile.materials[it.material]=(profile.materials[it.material]||0)+it.qty}else if(it.kind==='weapon'){if(!it._fromProfile)profile.stash.push(cleanWeaponItem(it))}else profile.stash.push(it)}if(currentIsLoot){const old=profile.weapons[run.weapon.type];if(old)profile.stash.push(cleanWeaponItem(old));profile.weapons[run.weapon.type]=cleanWeaponItem(run.weapon);profile.selected=run.weapon.type}else if(run.weapon&&run.weapon._fromProfile){profile.weapons[run.weapon._profileType]=cleanWeaponItem(run.weapon);profile.selected=run.weapon.type}profile.ammo.arrow+=run.ammo.arrow;profile.ammo.mana+=run.ammo.mana;profile.ammo.bullet+=run.ammo.bullet;profile.potions+=run.potions;profile.scrolls+=run.scrolls;save();toast(viaScroll?'귀환 성공! 전리품과 장비를 회수했습니다.':'B1 탈출 성공! 전리품과 장비를 회수했습니다.');endRun(false)}\nfunction endRun(lost=true){if(lost)restoreCarriedProfileGear();save();run=null;$('#dungeonView').classList.add('hidden');$('#lobbyView').classList.remove('hidden');closeLoot();renderLobby()}",
'escapeRun/endRun')

