"function fireEnemy(e,kind){const a=Math.atan2(run.player.y-e.y,run.player.x-e.x),sp=kind==='bomb'?190:kind==='sniper'?620:330;run.enemyShots.push({x:e.x,y:e.y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,r:kind==='bomb'?8:4,kind,damage:enemyTypes[e.type].damage,life:kind==='bomb'?1.15:2})}\nfunction lineBlocked(x1,y1,x2,y2){const obs=getCollisionRects(run.floorStates[run.floor]),dist=Math.hypot(x2-x1,y2-y1),steps=Math.ceil(dist/14);for(let i=1;i<steps;i++){const t=i/steps,x=x1+(x2-x1)*t,y=y1+(y2-y1)*t;if(rectCollide(x,y,3,obs))return true}return false}\nfunction castEnemyArea(e,damage,radius=76,delay=.95,label='저주 마법'){if(!run.enemyAreas)run.enemyAreas=[];const tx=run.player.x,ty=run.player.y;if(lineBlocked(e.x,e.y,tx,ty))return false;run.enemyAreas.push({x:tx,y:ty,r:radius,time:delay,max:delay,damage,label,exploded:false,blast:0});return true}\nfunction updateEnemyAreas(dt){if(!run.enemyAreas)return;for(const a of run.enemyAreas){if(!a.exploded){a.time-=dt;if(a.time<=0){a.exploded=true;a.blast=.24;if(Math.hypot(run.player.x-a.x,run.player.y-a.y)<=a.r+run.player.r)damagePlayer(a.damage,a.label,'mage');run.shake=Math.max(run.shake||0,4)}}else a.blast-=dt}run.enemyAreas=run.enemyAreas.filter(a=>!a.exploded||a.blast>0)}",
